export const a2Lessons: A2Lesson[] = [{"id":1,"unit":"واحد ۱ · روایت گذشته","title":"گذشته ساده با افعال باقاعده","description":"درباره اتفاق‌هایی که در گذشته تمام شده‌اند صحبت کن.","goal":"ساخت جمله مثبت در گذشته با فعل‌های باقاعده و تلفظ پایان ‎-ed.","explanation":"برای بیان رویداد تمام‌شده در گذشته از Past Simple استفاده می‌کنیم. در فعل باقاعده معمولاً ‎-ed اضافه می‌شود: work → worked. زمان‌هایی مثل yesterday و last week به فهم زمان کمک می‌کنند.","steps":[["ساخت مثبت","فاعل + شکل گذشته فعل: I watched a film yesterday."],["افزودن ‎-ed","بیشتر فعل‌ها ‎-ed می‌گیرند؛ live → lived و study → studied."],["املای فعل","اگر فعل به consonant + y ختم شود، y به ied تبدیل می‌شود: study → studied."],["تلفظ ‎-ed","سه تلفظ /t/، /d/ و /ɪd/ وجود دارد؛ wanted معمولاً /ɪd/ و watched معمولاً /t/ است."]],"vocabulary":[["yesterday","دیروز"],["last week","هفته گذشته"],["visited","دیدار کرد"],["watched","تماشا کرد"],["studied","مطالعه کرد"],["arrived","رسید"]],"examples":[["I visited my aunt last Friday.","جمعه گذشته به دیدن خاله‌ام رفتم.","visited شکل گذشته باقاعده visit است."],["She studied English yesterday.","او دیروز انگلیسی خواند.","چون study به همخوان + y ختم می‌شود، به studied تبدیل می‌شود."]],"dialogue":[["A","What did you do yesterday?","دیروز چه کار کردی؟"],["B","I stayed home and watched a film.","خانه ماندم و فیلم دیدم."],["A","Did you enjoy it?","از آن لذت بردی؟"],["B","Yes, it was great.","بله، عالی بود."]],"reading":"Last Saturday, Mina visited her cousin. They cooked lunch, listened to music and watched a comedy. Mina arrived home at eight o'clock. She enjoyed the day because she spent time with her family.","readingFa":"شنبه گذشته، مینا به دیدن پسرعمویش رفت. آن‌ها ناهار پختند، موسیقی گوش دادند و یک فیلم کمدی دیدند. مینا ساعت هشت به خانه رسید. از آن روز لذت برد چون با خانواده‌اش وقت گذراند.","mistakes":"بعد از did در سؤال، فعل به شکل ساده می‌آید؛ اما در جمله مثبت فعل گذشته است. برای مثال: Did you watched? نادرست است.","writing":"در ۵ تا ۷ جمله بنویس آخر هفته گذشته چه کار کردی. دست‌کم چهار فعل باقاعده به کار ببر.","questions":[["Choose the past form of clean.",["cleaned","cleaning","cleans"],0],["We ___ a museum last week.",["visit","visited","visiting"],1],["Which spelling is correct?",["studyed","studied","studys"],1],["The ‎-ed ending in watched is usually pronounced…",["/ɪd/","/d/","/t/"],2],["Which time expression refers to the past?",["tomorrow","next month","yesterday"],2]]},{"id":2,"unit":"واحد ۱ · روایت گذشته","title":"گذشته ساده با افعال بی‌قاعده","description":"افعال پرکاربردی را یاد بگیر که شکل گذشته‌شان تغییر می‌کند.","goal":"افعال بی‌قاعده رایج را در جمله مثبت تشخیص بدهی و درست استفاده کنی.","explanation":"بسیاری از فعل‌های پرکاربرد در گذشته ‎-ed نمی‌گیرند و شکل ویژه دارند. این شکل‌ها را باید همراه معنی یاد گرفت: go → went، see → saw، buy → bought.","steps":[["فعل‌های پرتکرار","go/went، have/had، do/did، see/saw و get/got را حفظ کن."],["جمله مثبت","فاعل + شکل گذشته: We went to the park."],["حفظ در گروه","فعل را با یک مثال و عبارت زمانی یاد بگیر؛ نه به‌صورت فهرست جدا."],["تفاوت شکل‌ها","شکل گذشته برای همه فاعل‌ها یکسان است: I went و she went."]],"vocabulary":[["went","رفت"],["saw","دید"],["bought","خرید"],["had","داشت"],["made","ساخت"],["took","برداشت / گرفت"]],"examples":[["He bought a new phone.","او یک گوشی جدید خرید.","buy در گذشته به bought تبدیل می‌شود."],["We saw our teacher at the station.","ما معلممان را در ایستگاه دیدیم.","شکل گذشته see برابر saw است."]],"dialogue":[["A","Where did you go on Sunday?","یکشنبه کجا رفتی؟"],["B","I went to the old town.","به شهر قدیمی رفتم."],["A","What did you see there?","آنجا چه دیدی؟"],["B","I saw a beautiful museum.","یک موزه زیبا دیدم."]],"reading":"Omid had a busy day yesterday. He got up early, took a bus to the city centre and met his friend. They ate lunch together and bought two tickets for a concert.","readingFa":"امید دیروز روز شلوغی داشت. زود بیدار شد، با اتوبوس به مرکز شهر رفت و دوستش را دید. آن‌ها با هم ناهار خوردند و دو بلیت کنسرت خریدند.","mistakes":"برای فعل بی‌قاعده شکل گذشته را یاد بگیر؛ goed و buyed نادرست‌اند. اما بعد از did، شکل ساده فعل می‌آید.","writing":"یک روز خاص را در ۶ جمله تعریف کن و دست‌کم پنج فعل بی‌قاعده استفاده کن.","questions":[["The past of go is…",["goed","went","gone"],1],["She ___ a lovely cake yesterday.",["made","maked","makes"],0],["We ___ lunch at one o'clock.",["have","had","has"],1],["The past of see is…",["saw","seed","seen"],0],["Which sentence is correct?",["He buyed a book.","He bought a book.","He buying a book."],1]]},{"id":3,"unit":"واحد ۱ · روایت گذشته","title":"سؤال و منفی در گذشته ساده","description":"درباره گذشته سؤال بپرس و بگو چه اتفاقی نیفتاد.","goal":"استفاده از did، didn't و شکل ساده فعل در سؤال و منفی.","explanation":"برای سؤال گذشته از Did + subject + base verb استفاده می‌کنیم. برای منفی از subject + didn't + base verb. چون did گذشته را نشان می‌دهد، فعل اصلی دیگر گذشته نمی‌شود.","steps":[["سؤال بله/خیر","Did you call your friend? — Yes, I did."],["سؤال با کلمه پرسشی","Where did they stay? کلمه پرسشی قبل از did می‌آید."],["منفی","I didn't watch TV. بعد از didn't فعل ساده می‌آید."],["پاسخ کوتاه","Yes, she did. / No, she didn't."]],"vocabulary":[["did","فعل کمکی گذشته"],["didn't","نکرد / نـ"],["stay","اقامت کردن"],["call","تماس گرفتن"],["because","زیرا"],["why","چرا"]],"examples":[["Did you finish your homework?","تکالیفت را تمام کردی؟","did پیش از فاعل می‌آید و finish ساده می‌ماند."],["They didn't travel by train.","آن‌ها با قطار سفر نکردند.","بعد از didn't از travel استفاده می‌کنیم."]],"dialogue":[["A","Did you go to the party?","به مهمانی رفتی؟"],["B","No, I didn't. I was tired.","نه. خسته بودم."],["A","Why didn't you come?","چرا نیامدی؟"],["B","Because I had a headache.","چون سردرد داشتم."]],"reading":"Sara planned to visit the library, but she didn't go because it was closed. She called her friend and asked, 'Did you finish the project?' Her friend said, 'Yes, I did.'","readingFa":"سارا قصد داشت به کتابخانه برود، اما نرفت چون بسته بود. او به دوستش زنگ زد و پرسید: «پروژه را تمام کردی؟» دوستش گفت: «بله.»","mistakes":"Did you went? و She didn't liked it نادرست‌اند. بعد از did و didn't همیشه شکل پایه فعل را بیاور.","writing":"۵ سؤال درباره دیروز بنویس و برای هرکدام یک پاسخ کوتاه مثبت یا منفی بده.","questions":[["___ you see Ali yesterday?",["Do","Did","Were"],1],["I didn't ___ the message.",["saw","seen","see"],2],["Which is correct?",["Did she call you?","Did she called you?","Does she called you?"],0],["They ___ visit us last night.",["didn't","weren't","doesn't"],0],["Where ___ he buy the ticket?",["does","was","did"],2]]},{"id":4,"unit":"واحد ۲ · توصیف و مقایسه","title":"افعال was و were","description":"وضعیت، مکان و احساسات گذشته را توصیف کن.","goal":"انتخاب was یا were و ساخت سؤال و منفی با فعل be در گذشته.","explanation":"گذشته am و is برابر was است و گذشته are برابر were. از was با I/he/she/it و از were با you/we/they استفاده می‌کنیم.","steps":[["جمله مثبت","I was at home. / They were happy."],["جمله منفی","wasn't و weren't: He wasn't late."],["سؤال","Was she tired? / Were they at school?"],["پاسخ کوتاه","Yes, I was. / No, they weren't."]],"vocabulary":[["yesterday","دیروز"],["excited","هیجان‌زده"],["afraid","ترسیده"],["crowded","شلوغ"],["quiet","ساکت"],["at home","در خانه"]],"examples":[["The film was interesting.","فیلم جالب بود.","برای film مفرد از was استفاده می‌کنیم."],["We were at the station.","ما در ایستگاه بودیم.","برای we از were استفاده می‌شود."]],"dialogue":[["A","Were you at school yesterday?","دیروز مدرسه بودی؟"],["B","No, I wasn't. I was ill.","نه، نبودم. بیمار بودم."],["A","Was the doctor helpful?","دکتر کمک‌کننده بود؟"],["B","Yes, she was.","بله."]],"reading":"The weather was cold last Sunday. My friends were at my house, so we stayed inside. The film was funny and everyone was happy.","readingFa":"یکشنبه گذشته هوا سرد بود. دوستانم خانه من بودند، بنابراین داخل ماندیم. فیلم خنده‌دار بود و همه خوشحال بودند.","mistakes":"برای you همیشه were به کار می‌رود، حتی وقتی درباره یک نفر صحبت می‌کنی. در سؤال، was/were قبل از فاعل می‌آید.","writing":"اتاق، مدرسه یا شهر خود را در یک روز گذشته با ۵ جمله توصیف کن.","questions":[["I ___ very tired yesterday.",["was","were","am"],0],["They ___ at the cinema.",["was","are","were"],2],["___ your parents at home?",["Was","Were","Did"],1],["She wasn't ___ yesterday.",["happy","were happy","be happy"],0],["Which short answer is correct? Were you busy? — No, ___.",["I didn't","I weren't","I wasn't"],2]]},{"id":5,"unit":"واحد ۲ · توصیف و مقایسه","title":"صفت‌های مقایسه‌ای","description":"دو نفر، مکان یا وسیله را با هم مقایسه کن.","goal":"ساخت comparative با ‎-er و more و استفاده از than.","explanation":"برای مقایسه دو چیز، صفت را به شکل comparative می‌آوریم. صفت‌های کوتاه معمولاً ‎-er می‌گیرند: tall → taller. صفت‌های بلند معمولاً با more می‌آیند: more interesting. سپس than می‌آید.","steps":[["صفت کوتاه","small → smaller؛ اگر به e ختم شود فقط r اضافه کن: nice → nicer."],["الگوی consonant-vowel-consonant","گاهی حرف پایانی دوبرابر می‌شود: big → bigger."],["صفت بلند","more + adjective: more expensive."],["بی‌قاعده‌ها","good → better و bad → worse."]],"vocabulary":[["than","از (در مقایسه)"],["cheaper","ارزان‌تر"],["faster","سریع‌تر"],["more comfortable","راحت‌تر"],["better","بهتر"],["worse","بدتر"]],"examples":[["A train is faster than a bus.","قطار از اتوبوس سریع‌تر است.","faster شکل مقایسه‌ای fast است."],["This exercise is more difficult than the last one.","این تمرین از تمرین قبلی دشوارتر است.","برای difficult از more استفاده می‌کنیم."]],"dialogue":[["A","Which phone is better?","کدام گوشی بهتر است؟"],["B","The black one is cheaper.","مشکی ارزان‌تر است."],["A","But the silver one is more modern.","اما نقره‌ای مدرن‌تر است."],["B","You're right. Let's compare the cameras.","درست می‌گویی. دوربین‌ها را مقایسه کنیم."]],"reading":"The city bus is cheaper than a taxi, but a taxi is more comfortable. Walking is healthier than driving for short distances.","readingFa":"اتوبوس شهری از تاکسی ارزان‌تر است، اما تاکسی راحت‌تر است. برای مسیرهای کوتاه پیاده‌روی از رانندگی سالم‌تر است.","mistakes":"more cheaper نادرست است؛ برای صفت کوتاه فقط ‎-er کافی است. همچنین than را با then اشتباه نگیر.","writing":"دو گوشی، دو شهر یا دو ورزش را با دست‌کم چهار جمله مقایسه کن.","questions":[["The comparative of tall is…",["more tall","taller","tallest"],1],["This bag is ___ than that one.",["cheap","cheaper","cheapest"],1],["English is ___ than I expected.",["more interesting","interestinger","most interesting"],0],["The comparative of good is…",["gooder","best","better"],2],["Which sentence is correct?",["My car is more faster.","My car is faster than yours.","My car faster than yours."],1]]},{"id":6,"unit":"واحد ۲ · توصیف و مقایسه","title":"صفات عالی","description":"بگو کدام مورد از همه بزرگ‌تر، بهترین یا جالب‌ترین است.","goal":"ساخت superlative با ‎-est و most و استفاده از the.","explanation":"برای مقایسه یک مورد با همه اعضای گروه از superlative استفاده می‌کنیم. صفت کوتاه معمولاً ‎-est می‌گیرد و پیش از آن the می‌آید: the tallest. صفت بلند با the most ساخته می‌شود.","steps":[["صفت کوتاه","small → the smallest؛ nice → the nicest."],["تغییر املایی","big → the biggest؛ happy → the happiest."],["صفت بلند","the most beautiful و the most expensive."],["بی‌قاعده‌ها","good → the best و bad → the worst."]],"vocabulary":[["the biggest","بزرگ‌ترین"],["the oldest","قدیمی‌ترین"],["the best","بهترین"],["the worst","بدترین"],["the most popular","محبوب‌ترین"],["in the class","در کلاس"]],"examples":[["Mount Everest is the highest mountain in the world.","اورست بلندترین کوه جهان است.","از the + صفت عالی استفاده می‌کنیم."],["This is the most useful app on my phone.","این مفیدترین برنامه گوشی من است.","useful صفتی است که با most می‌آید."]],"dialogue":[["A","What's the best place in your town?","بهترین جای شهرت کجاست؟"],["B","The old park is the most beautiful.","پارک قدیمی زیباترین است."],["A","Is it the biggest park?","بزرگ‌ترین پارک هم هست؟"],["B","No, but it's the quietest.","نه، اما ساکت‌ترین است."]],"reading":"Our class chose the most interesting project. It was about the oldest buildings in our town. The students said the final presentation was the best part.","readingFa":"کلاس ما جالب‌ترین پروژه را انتخاب کرد. موضوع آن ساختمان‌های قدیمی شهرمان بود. دانش‌آموزان گفتند ارائه پایانی بهترین بخش بود.","mistakes":"برای ساخت عالی، most و ‎-est را هم‌زمان به یک صفت اضافه نکن. the most tallest نادرست است.","writing":"سه مکان محبوبت را رتبه‌بندی کن و با صفات عالی توضیح بده.","questions":[["The superlative of small is…",["the smaller","the smallest","the most small"],1],["This is ___ film I've seen.",["the best","better","good"],0],["Which is correct?",["the most beautiful","the beautifullest","most beautifulest"],0],["The superlative of bad is…",["the baddest","the worst","the worse"],1],["She is ___ student in our group.",["the youngest","younger","young"],0]]},{"id":7,"unit":"واحد ۳ · برنامه‌ها و آینده","title":"آینده با be going to","description":"درباره برنامه‌ها و قصدهای آینده صحبت کن.","goal":"ساخت جمله مثبت، منفی و سؤالی با be going to.","explanation":"از be going to برای برنامه یا قصدی که از قبل شکل گرفته و نیز پیش‌بینی بر اساس نشانه‌های فعلی استفاده می‌کنیم. ساختار: am/is/are + going to + base verb.","steps":[["مثبت","I'm going to study tonight."],["منفی","She isn't going to travel next week."],["سؤال","Are they going to join us?"],["پیش‌بینی با نشانه","Look at those clouds. It's going to rain."]],"vocabulary":[["plan","برنامه"],["intend","قصد داشتن"],["next weekend","آخر هفته آینده"],["book a ticket","بلیت رزرو کردن"],["probably","احتمالاً"],["cloudy","ابری"]],"examples":[["We're going to visit our grandparents.","قرار است به دیدن پدربزرگ و مادربزرگمان برویم.","برنامه از قبل مشخص شده است."],["Look! The glass is going to fall.","نگاه کن! لیوان در حال افتادن است.","پیش‌بینی بر اساس نشانه قابل مشاهده است."]],"dialogue":[["A","What are you going to do this summer?","تابستان امسال قصد داری چه کار کنی؟"],["B","I'm going to take an English course.","می‌خواهم در یک دوره انگلیسی شرکت کنم."],["A","Are you going to study every day?","قرار است هر روز درس بخوانی؟"],["B","Yes, I am.","بله."]],"reading":"Laleh is going to spend her holiday in Tabriz. She is going to travel by train and stay with her aunt. She isn't going to take many bags because the trip is short.","readingFa":"لاله قرار است تعطیلاتش را در تبریز بگذراند. او با قطار سفر می‌کند و خانه خاله‌اش می‌ماند. چون سفر کوتاه است، قرار نیست چمدان‌های زیادی ببرد.","mistakes":"بعد از going to فعل ساده می‌آید؛ going to went نادرست است. فعل be را هم فراموش نکن.","writing":"برنامه سه روز آینده‌ات را با پنج جمله be going to بنویس.","questions":[["I ___ going to call you.",["am","is","are"],0],["They are going to ___ a new house.",["bought","buy","buying"],1],["___ she going to come?",["Do","Is","Does"],1],["We ___ going to stay home.",["isn't","am not","aren't"],2],["Which use is correct?",["A plan for next week","A finished event yesterday","A habit every day"],0]]},{"id":8,"unit":"واحد ۳ · برنامه‌ها و آینده","title":"آینده با will","description":"پیش‌بینی، تصمیم لحظه‌ای و قول دادن را بیان کن.","goal":"استفاده از will و won't و سؤال با will.","explanation":"will برای پیش‌بینی، تصمیمی که همان لحظه می‌گیریم و قول یا پیشنهاد به کار می‌رود. پس از will همیشه شکل ساده فعل می‌آید و برای همه فاعل‌ها یکسان است.","steps":[["مثبت","I will help you. شکل کوتاه: I'll help you."],["منفی","will not = won't: It won't take long."],["سؤال","Will you be here tomorrow?"],["تصمیم لحظه‌ای","The phone is ringing. I'll answer it."]],"vocabulary":[["promise","قول"],["perhaps","شاید"],["I think","فکر می‌کنم"],["certainly","قطعاً"],["help","کمک کردن"],["answer","پاسخ دادن"]],"examples":[["I think our team will win.","فکر می‌کنم تیم ما برنده خواهد شد.","یک پیش‌بینی با I think است."],["I'll carry that bag for you.","آن کیف را برایت حمل می‌کنم.","تصمیم و پیشنهاد در لحظه است."]],"dialogue":[["A","I'm worried about the exam.","نگران امتحانم."],["B","Don't worry. I'll help you study.","نگران نباش. کمکت می‌کنم درس بخوانی."],["A","Will you have time tonight?","امشب وقت خواهی داشت؟"],["B","Yes, I will.","بله."]],"reading":"The weather report says it will be sunny tomorrow. We will probably go hiking. If it gets cold, we'll take our jackets.","readingFa":"گزارش هواشناسی می‌گوید فردا هوا آفتابی خواهد بود. احتمالاً به پیاده‌روی در طبیعت می‌رویم. اگر هوا سرد شود، ژاکت‌هایمان را می‌بریم.","mistakes":"بعد از will فعل ساده می‌آید؛ will goes نادرست است. will برای همه فاعل‌ها یکسان است.","writing":"سه پیش‌بینی درباره سال آینده و دو قولی که می‌توانی بدهی بنویس.","questions":[["I think she ___ pass the test.",["will","is","does"],0],["Don't worry. I ___ help you.",["helped","will","am"],1],["The negative of will is…",["don't","won't","isn't"],1],["___ you come tomorrow?",["Do","Are","Will"],2],["After will, use…",["the base verb","verb + s","past form"],0]]},{"id":9,"unit":"واحد ۳ · برنامه‌ها و آینده","title":"حال استمراری برای برنامه قطعی","description":"قرارهای مشخص و برنامه‌های هماهنگ‌شده را بیان کن.","goal":"تمایز present continuous برای برنامه قطعی آینده از going to.","explanation":"حال استمراری معمولاً برای کاری که همین حالا در جریان است به کار می‌رود؛ اما برای قرار و برنامه‌ای که هماهنگ شده، می‌توان از آن با زمان آینده استفاده کرد: I'm meeting Sara at six.","steps":[["ساختار","am/is/are + verb-ing؛ زمان آینده مثل tomorrow یا tonight معنای آینده را روشن می‌کند."],["قرار مشخص","We're having dinner with Ali on Friday."],["تفاوت با going to","going to بیشتر قصد و برنامه کلی است؛ present continuous بر قرار هماهنگ‌شده تأکید دارد."],["سؤال","What are you doing this evening?"]],"vocabulary":[["appointment","قرار ملاقات"],["arrangement","هماهنگی"],["tonight","امشب"],["at six","ساعت شش"],["meet","ملاقات کردن"],["schedule","برنامه زمانی"]],"examples":[["I'm seeing the dentist on Monday.","دوشنبه به دندان‌پزشک مراجعه می‌کنم.","یک قرار مشخص تنظیم شده است."],["They're flying to Rome tomorrow.","آن‌ها فردا به رم پرواز می‌کنند.","بلیط یا برنامه سفر از قبل هماهنگ شده است."]],"dialogue":[["A","What are you doing on Friday?","جمعه چه برنامه‌ای داری؟"],["B","I'm meeting my cousin for lunch.","برای ناهار پسرعمویم را می‌بینم."],["A","Are you going by car?","با ماشین می‌روی؟"],["B","No, we're taking the train.","نه، با قطار می‌رویم."]],"reading":"Neda is meeting her classmates at the station at 9 a.m. They are travelling to a nearby village. Their teacher is joining them, too.","readingFa":"ندا ساعت ۹ صبح در ایستگاه با هم‌کلاسی‌هایش قرار دارد. آن‌ها به روستایی نزدیک سفر می‌کنند. معلمشان نیز همراه آن‌ها می‌شود.","mistakes":"برای برنامه آینده، زمان آینده را مشخص کن. بدون نشانه زمانی، جمله I'm meeting Ali می‌تواند به برنامه نزدیک اشاره کند اما زمینه مهم است.","writing":"تقویم آخر هفته‌ات را با چهار جمله حال استمراری و زمان آینده توصیف کن.","questions":[["I ___ my friend at 5 tomorrow.",["meet","am meeting","met"],1],["Which phrase shows a future arrangement?",["I'm seeing the doctor on Tuesday.","I see him every day.","I saw him yesterday."],0],["They ___ dinner with us tonight.",["are having","has","had"],0],["Choose the correct question.",["What are you doing tomorrow?","What do you doing tomorrow?","What you are do tomorrow?"],0],["Present continuous for future usually describes…",["a fixed arrangement","a general fact","a past habit"],0]]},{"id":10,"unit":"واحد ۴ · تجربه و زندگی","title":"حال کامل: تجربه‌های زندگی","description":"درباره تجربه‌هایی صحبت کن که زمان دقیقشان مهم نیست.","goal":"آشنایی کاربردی با present perfect با have/has + past participle و ever/never.","explanation":"حال کامل برای تجربه تا زمان حال به کار می‌رود؛ زمان دقیق انجام کار معمولاً گفته نمی‌شود. ساختار: have/has + past participle. ever در سؤال و never برای تجربه نداشتن رایج است.","steps":[["ساختار","I have visited London. / She has tried sushi."],["سؤال تجربه","Have you ever travelled by plane?"],["پاسخ منفی","I've never ridden a horse."],["شکل سوم فعل","برای فعل باقاعده معمولاً ‎-ed و برای بی‌قاعده شکل سوم: see → seen."]],"vocabulary":[["ever","تا به حال"],["never","هرگز"],["experience","تجربه"],["visited","بازدید کرده"],["tried","امتحان کرده"],["ridden","سوار شده"]],"examples":[["Have you ever eaten Japanese food?","آیا تا به حال غذای ژاپنی خورده‌ای؟","ever درباره تجربه تا این لحظه سؤال می‌کند."],["I've never flown in a helicopter.","من هرگز با هلیکوپتر پرواز نکرده‌ام.","never تجربه نداشتن را نشان می‌دهد."]],"dialogue":[["A","Have you ever been to Istanbul?","تا به حال استانبول بوده‌ای؟"],["B","Yes, I have. I've visited it twice.","بله. دو بار از آن دیدن کرده‌ام."],["A","Have you tried the local food?","غذای محلی را امتحان کرده‌ای؟"],["B","No, I haven't.","نه."]],"reading":"Arman has tried many new activities this year. He has learned to cook pasta, has visited a science museum and has made a new friend. He hasn't travelled abroad yet.","readingFa":"آرمان امسال فعالیت‌های جدید زیادی را تجربه کرده است. آشپزی پاستا یاد گرفته، از موزه علوم دیدن کرده و دوست جدیدی پیدا کرده است. او هنوز به خارج از کشور سفر نکرده است.","mistakes":"اگر زمان دقیق گذشته را می‌گویی، معمولاً past simple مناسب است: I went there in 2022. برای تجربه بدون زمان دقیق، present perfect.","writing":"پنج تجربه‌ای را که داشته‌ای یا نداشته‌ای با ever/never یا جمله مثبت بنویس.","questions":[["Have you ever ___ to Paris?",["been","be","was"],0],["She has never ___ sushi.",["eat","eaten","ate"],1],["The structure is…",["have + base verb","have/has + past participle","did + past participle"],1],["Which word is common in experience questions?",["ever","yesterday","last"],0],["I ___ never flown.",["has","did","have"],2]]},{"id":11,"unit":"واحد ۴ · تجربه و زندگی","title":"حال کامل و گذشته ساده","description":"تفاوت تجربه تا امروز با رویداد در زمان مشخص گذشته را بفهم.","goal":"انتخاب درست بین present perfect و past simple.","explanation":"Past simple برای زمان تمام‌شده و مشخص مثل last year یا yesterday است. Present perfect برای تجربه یا نتیجه مرتبط با زمان حال است و زمان دقیق گذشته را بیان نمی‌کند.","steps":[["زمان مشخص گذشته","I saw that film last night. زمان مشخص و تمام‌شده است."],["تجربه تا حال","I've seen that film. تجربه مهم است، نه زمان دقیق."],["already و yet","already معمولاً در جمله مثبت و yet در سؤال و منفی می‌آید."],["just","just برای کاری که همین چند لحظه پیش انجام شده به کار می‌رود."]],"vocabulary":[["already","قبلاً / تا الان"],["yet","هنوز / تا حالا"],["just","همین الان"],["last year","سال گذشته"],["recently","اخیراً"],["finished","تمام‌شده"]],"examples":[["I've already finished my homework.","من تکالیفم را قبلاً تمام کرده‌ام.","already بر کامل شدن تا الان تأکید دارد."],["I finished it at seven.","آن را ساعت هفت تمام کردم.","زمان مشخص است؛ past simple."]],"dialogue":[["A","Have you done your project yet?","پروژه‌ات را هنوز انجام داده‌ای؟"],["B","Yes, I've just finished it.","بله، همین الان تمامش کردم."],["A","When did you finish?","چه زمانی تمام کردی؟"],["B","Ten minutes ago.","ده دقیقه پیش."]],"reading":"Mina has already packed her bag, but she hasn't printed her ticket yet. She booked the trip two weeks ago and paid for it yesterday.","readingFa":"مینا چمدانش را بسته، اما هنوز بلیتش را چاپ نکرده است. او سفر را دو هفته پیش رزرو کرد و دیروز هزینه‌اش را پرداخت کرد.","mistakes":"با yesterday و last week از present perfect استفاده نکن. ago نیز معمولاً با past simple می‌آید.","writing":"چهار جمله درباره کارهایی که تا الان انجام داده‌ای و سه جمله درباره زمان مشخص گذشته بنویس.","questions":[["I ___ that book last month.",["have read","read","has read"],1],["She hasn't called me ___.",["yet","already","ago"],0],["We have ___ arrived.",["yesterday","just","last"],1],["Which is correct?",["I've seen him yesterday.","I saw him yesterday.","I have saw him yesterday."],1],["Have you finished your work ___?",["yet","ago","last"],0]]},{"id":12,"unit":"واحد ۵ · مقدار و خرید","title":"some، any و no","description":"مقدار نامشخص را در جمله مثبت، منفی و سؤال بیان کن.","goal":"انتخاب some و any و no در موقعیت‌های روزمره.","explanation":"some بیشتر در جمله مثبت و پیشنهاد یا درخواست استفاده می‌شود. any معمولاً در سؤال و منفی می‌آید. no پیش از اسم، معنی نبودن می‌دهد: There is no milk.","steps":[["مثبت","There are some apples."],["سؤال و منفی","Are there any eggs? / There aren't any eggs."],["پیشنهاد و درخواست","Would you like some tea? Can I have some water?"],["no","There is no sugar یعنی هیچ شکری وجود ندارد."]],"vocabulary":[["some","مقداری / چند"],["any","هیچ / مقداری در سؤال"],["no","هیچ"],["milk","شیر"],["sugar","شکر"],["enough","کافی"]],"examples":[["We need some bread.","به مقداری نان نیاز داریم.","some در جمله مثبت آمده است."],["Are there any clean cups?","آیا فنجان تمیزی هست؟","any در سؤال معمولی استفاده می‌شود."]],"dialogue":[["A","Is there any milk?","شیر هست؟"],["B","Yes, there's some in the fridge.","بله، مقداری در یخچال هست."],["A","Are there any eggs?","تخم‌مرغی هست؟"],["B","No, there aren't any.","نه، هیچ‌کدام نیست."]],"reading":"We have some rice and vegetables, but we don't have any cheese. There is no juice in the fridge, so I'll buy some after work.","readingFa":"مقداری برنج و سبزیجات داریم، اما پنیر نداریم. هیچ آبمیوه‌ای در یخچال نیست، پس بعد از کار مقداری می‌خرم.","mistakes":"در جمله منفی معمولاً any می‌آید؛ از no و not any هم‌زمان استفاده نکن: I don't have no money نادرست است.","writing":"فهرست خرید خانه را با some، any و no در ۶ جمله بنویس.","questions":[["There are ___ oranges on the table.",["some","any","no any"],0],["Do we have ___ coffee?",["some","any","a"],1],["I don't have ___ free time today.",["some","any","no"],1],["Would you like ___ tea?",["any","some","no"],1],["Which is correct?",["There is no bread.","There isn't no bread.","There are no bread."],0]]},{"id":13,"unit":"واحد ۵ · مقدار و خرید","title":"much، many، a lot of و a few","description":"درباره تعداد و مقدار دقیق‌تر صحبت کن.","goal":"تمایز اسم قابل‌شمارش و غیرقابل‌شمارش و استفاده از quantifiers.","explanation":"many با اسم جمع قابل‌شمارش می‌آید؛ much با اسم غیرقابل‌شمارش. a lot of با هر دو ممکن است. a few برای تعداد کم اما موجود و a little برای مقدار کم به کار می‌رود.","steps":[["many","many books، many people."],["much","much water، much time؛ در سؤال و منفی رایج‌تر است."],["a lot of","a lot of friends و a lot of work."],["a few / a little","a few apples یعنی چند سیب؛ a little milk یعنی کمی شیر."]],"vocabulary":[["many","تعداد زیاد"],["much","مقدار زیاد"],["a lot of","مقدار / تعداد زیاد"],["a few","چند تا"],["a little","کمی"],["plenty of","به مقدار کافی و زیاد"]],"examples":[["How many students are there?","چند دانش‌آموز وجود دارد؟","students قابل‌شمارش و جمع است."],["How much time do we need?","چقدر زمان نیاز داریم؟","time غیرقابل‌شمارش است."]],"dialogue":[["A","How many apples should I buy?","چند سیب بخرم؟"],["B","Just a few. We have a lot of fruit.","فقط چندتا. میوه زیادی داریم."],["A","How much milk is left?","چقدر شیر مانده؟"],["B","A little.","کمی."]],"reading":"There are a few shops near my house and a lot of cafés. There isn't much traffic in the morning, but there are many cars in the evening.","readingFa":"نزدیک خانه‌ام چند مغازه و کافه‌های زیادی وجود دارد. صبح ترافیک زیادی نیست، اما عصر ماشین‌های زیادی هستند.","mistakes":"many برای اسم قابل‌شمارش جمع و much برای غیرقابل‌شمارش است. many money و much books نادرست‌اند.","writing":"درباره یخچال یا محله‌ات با much، many، a lot of و a few پنج جمله بنویس.","questions":[["How ___ chairs do we need?",["much","many","little"],1],["How ___ water is in the bottle?",["many","few","much"],2],["I have ___ friends in this city.",["a little","a few","much"],1],["There is ___ information online.",["many","a lot of","a few"],1],["Which noun is uncountable?",["chairs","apples","money"],2]]},{"id":14,"unit":"واحد ۶ · قوانین و توصیه","title":"should و shouldn't","description":"توصیه و پیشنهاد دوستانه بده.","goal":"ساخت توصیه با should و shouldn't و پرسیدن نظر.","explanation":"should برای توصیه و پیشنهاد مناسب است و shouldn't برای توصیه به انجام ندادن. بعد از هر دو، فعل ساده و بدون to می‌آید.","steps":[["توصیه مثبت","You should get some rest."],["توصیه منفی","You shouldn't eat too much sugar."],["سؤال","Should I call the doctor?"],["پاسخ و دلیل","I think you should… برای بیان نظر و توصیه."]],"vocabulary":[["advice","توصیه"],["should","بهتر است"],["shouldn't","بهتر نیست"],["rest","استراحت"],["exercise","ورزش"],["healthy","سالم"]],"examples":[["You should drink more water.","بهتر است آب بیشتری بنوشی.","should + فعل ساده."],["He shouldn't stay up late.","او نباید تا دیروقت بیدار بماند.","shouldn't توصیه منفی است."]],"dialogue":[["A","I have a headache.","سردرد دارم."],["B","You should rest and drink water.","بهتر است استراحت کنی و آب بنوشی."],["A","Should I go to school?","به مدرسه بروم؟"],["B","I think you should stay home today.","فکر می‌کنم بهتر است امروز خانه بمانی."]],"reading":"If you want to learn a language, you should practise a little every day. You shouldn't be afraid of making mistakes. You should also listen to short conversations.","readingFa":"اگر می‌خواهی زبانی یاد بگیری، بهتر است هر روز کمی تمرین کنی. نباید از اشتباه کردن بترسی. همچنین بهتر است به مکالمه‌های کوتاه گوش بدهی.","mistakes":"بعد از should فعل ساده می‌آید؛ should to go و should goes نادرست‌اند.","writing":"برای دوستی که می‌خواهد انگلیسی یاد بگیرد، پنج توصیه با should و shouldn't بنویس.","questions":[["You ___ see a dentist about that tooth.",["should","shouldn't","are"],0],["You shouldn't ___ so late.",["to sleep","sleep","sleeping"],1],["___ I take an umbrella?",["Do","Should","Am"],1],["Which is advice?",["You should practise daily.","You practised yesterday.","You are practising now."],0],["The negative form is…",["don't should","shouldn't","not should"],1]]},{"id":15,"unit":"واحد ۶ · قوانین و توصیه","title":"must، mustn't و have to","description":"الزام، ضرورت و ممنوعیت را بیان کن.","goal":"تمایز must و have to و mustn't و don't have to.","explanation":"must و have to برای الزام‌اند. mustn't یعنی انجام آن ممنوع است؛ don't have to یعنی لازم نیست، اما ممنوع هم نیست. بعد از must فعل ساده می‌آید.","steps":[["must","قانون یا الزام قوی: You must wear a seat belt."],["have to","ضرورت یا الزام بیرونی: I have to work tomorrow."],["mustn't","ممنوعیت: You mustn't park here."],["don't have to","نبود الزام: You don't have to bring food."]],"vocabulary":[["rule","قانون"],["allowed","مجاز"],["forbidden","ممنوع"],["necessary","ضروری"],["permission","اجازه"],["helmet","کلاه ایمنی"]],"examples":[["Students must arrive on time.","دانش‌آموزان باید به‌موقع برسند.","must الزام را بیان می‌کند."],["You don't have to pay today.","لازم نیست امروز پرداخت کنی.","نبود ضرورت را نشان می‌دهد، نه ممنوعیت."]],"dialogue":[["A","Do we have to wear uniforms?","باید لباس فرم بپوشیم؟"],["B","Yes, we do. It's a school rule.","بله. قانون مدرسه است."],["A","Can we use phones in class?","می‌توانیم در کلاس از گوشی استفاده کنیم؟"],["B","No, you mustn't.","نه، ممنوع است."]],"reading":"At the museum, visitors must keep quiet. They mustn't touch the paintings. You don't have to buy a ticket for children under five.","readingFa":"در موزه، بازدیدکنندگان باید سکوت کنند. نباید به نقاشی‌ها دست بزنند. برای کودکان زیر پنج سال لازم نیست بلیت بخرید.","mistakes":"mustn't به معنی «نباید/ممنوع است» است؛ don't have to به معنی «لازم نیست» است. این دو قابل‌جایگزینی نیستند.","writing":"برای کتابخانه یا کلاس خود پنج قانون بنویس؛ حداقل دو مورد ممنوعیت باشد.","questions":[["You ___ stop at a red light.",["must","mustn't","don't have to"],0],["You ___ smoke here. It's forbidden.",["don't have to","mustn't","have to"],1],["You ___ bring a pen; we have extras.",["must","mustn't","don't have to"],2],["After must, use…",["to + verb","verb + ing","base verb"],2],["Which sentence means «لازم نیست»?",["You mustn't come.","You don't have to come.","You have to come."],1]]},{"id":16,"unit":"واحد ۷ · فعل‌ها و قیدها","title":"قیدهای حالت","description":"توضیح بده کارها چگونه انجام می‌شوند.","goal":"ساخت و جایگاه adverbs of manner مانند slowly و carefully.","explanation":"قید حالت معمولاً فعل را توصیف می‌کند و پاسخ می‌دهد کار چگونه انجام شده است. بسیاری از قیدها با افزودن ‎-ly به صفت ساخته می‌شوند: careful → carefully. برخی شکل ویژه دارند: good → well.","steps":[["ساخت قید","slow → slowly و quiet → quietly."],["تغییر املایی","easy → easily؛ happy → happily."],["قیدهای بی‌قاعده","good صفت است، well قید؛ fast در هر دو نقش یکسان است."],["جایگاه","قید معمولاً بعد از فعل یا مفعول می‌آید: She speaks clearly."]],"vocabulary":[["carefully","با دقت"],["quickly","به‌سرعت"],["quietly","آرام"],["well","خوب"],["hard","سخت / با تلاش"],["loudly","با صدای بلند"]],"examples":[["Please drive carefully.","لطفاً با دقت رانندگی کن.","carefully چگونگی رانندگی را توضیح می‌دهد."],["He speaks English very well.","او انگلیسی را خیلی خوب صحبت می‌کند.","well قید مناسب برای speak است."]],"dialogue":[["A","How did you finish so quickly?","چطور این‌قدر سریع تمام کردی؟"],["B","I worked carefully and didn't stop.","با دقت کار کردم و متوقف نشدم."],["A","You write very clearly, too.","خیلی واضح هم می‌نویسی."],["B","Thanks! I practise every day.","ممنون! هر روز تمرین می‌کنم."]],"reading":"The guide spoke slowly so everyone could understand. The children listened carefully and answered the questions correctly.","readingFa":"راهنما آهسته صحبت کرد تا همه بتوانند بفهمند. بچه‌ها با دقت گوش دادند و به سؤال‌ها درست پاسخ دادند.","mistakes":"بعد از look، feel و sound گاهی صفت می‌آید: She looks happy. اما برای توصیف فعل از قید استفاده می‌کنیم: She sings beautifully.","writing":"یک مهارت مثل آشپزی یا رانندگی را با پنج قید حالت توصیف کن.","questions":[["She sings ___.",["beautiful","beautifully","beautify"],1],["He speaks English very ___.",["good","well","best"],1],["The opposite of slowly is…",["slow","quickly","careful"],1],["The adverb of easy is…",["easyly","easily","easely"],1],["Which sentence is correct?",["Drive careful.","Drive carefully.","Careful drive."],1]]},{"id":17,"unit":"واحد ۷ · فعل‌ها و قیدها","title":"مصدر با to و فعل ing","description":"بعد از فعل‌های رایج، شکل درست فعل بعدی را انتخاب کن.","goal":"شناخت فعل‌هایی که پس از آن‌ها to-infinitive یا gerund می‌آید.","explanation":"بعضی فعل‌ها با to + base verb می‌آیند، مثل want to learn و need to go. بعضی فعل‌ها با ‎-ing می‌آیند، مثل enjoy reading و finish working. این الگوها را همراه فعل اصلی یاد بگیر.","steps":[["to-infinitive","want, need, hope, plan + to + فعل ساده."],["gerund","enjoy, finish, avoid, mind + فعل ing."],["پس از like/love","هر دو شکل ممکن‌اند: I like reading / I like to read."],["معنی را حفظ کن","ساختار فعل بعدی را همراه خود فعل یاد بگیر."]],"vocabulary":[["decide to","تصمیم گرفتن که"],["hope to","امیدوار بودن که"],["enjoy doing","لذت بردن از انجام"],["finish doing","تمام کردن"],["avoid doing","اجتناب کردن"],["learn to","یاد گرفتن"]],"examples":[["I hope to study abroad one day.","امیدوارم روزی خارج از کشور تحصیل کنم.","hope با to-infinitive می‌آید."],["She enjoys painting.","او از نقاشی کردن لذت می‌برد.","enjoy با gerund می‌آید."]],"dialogue":[["A","What do you enjoy doing?","از انجام چه کاری لذت می‌بری؟"],["B","I enjoy playing chess.","از شطرنج بازی کردن لذت می‌برم."],["A","Do you want to learn tennis?","می‌خواهی تنیس یاد بگیری؟"],["B","Yes, I hope to start next month.","بله، امیدوارم ماه آینده شروع کنم."]],"reading":"Reza decided to join a sports club. He enjoys swimming and wants to improve his fitness. He hopes to meet new people there.","readingFa":"رضا تصمیم گرفت به یک باشگاه ورزشی بپیوندد. او از شنا لذت می‌برد و می‌خواهد آمادگی جسمانی‌اش را بهتر کند. امیدوار است آنجا با افراد جدید آشنا شود.","mistakes":"enjoy to swim نادرست است؛ enjoy swimming درست است. want swimming هم در این معنی معمولاً درست نیست؛ want to swim بگو.","writing":"سه کاری را که دوست داری انجام بدهی و سه کاری را که از آن‌ها لذت می‌بری بنویس.","questions":[["I want ___ English.",["learning","learn","to learn"],2],["She enjoys ___ books.",["reading","to read","read"],0],["We decided ___ early.",["leave","to leave","leaving"],1],["He finished ___ his homework.",["doing","to do","do"],0],["Which verb is commonly followed by -ing?",["enjoy","want","hope"],0]]},{"id":18,"unit":"واحد ۸ · جمله‌های پیوسته","title":"because، so، when و if","description":"جمله‌ها را با دلیل، نتیجه و زمان به هم وصل کن.","goal":"استفاده از پیونددهنده‌های پایه برای ساخت جمله‌های طولانی‌تر.","explanation":"because دلیل را معرفی می‌کند؛ so نتیجه را. when زمان وقوع را نشان می‌دهد و if شرط را. ترتیب دو بخش جمله می‌تواند تغییر کند، اما اگر بخش when/if در ابتدا بیاید معمولاً ویرگول می‌گذاریم.","steps":[["دلیل","I stayed home because I was ill."],["نتیجه","It was raining, so we took a taxi."],["زمان","When I get home, I'll call you."],["شرط","If it rains, we'll stay inside."]],"vocabulary":[["because","زیرا"],["so","پس / بنابراین"],["when","وقتی که"],["if","اگر"],["although","اگرچه"],["while","درحالی‌که"]],"examples":[["I took a jacket because it was cold.","چون هوا سرد بود ژاکت برداشتم.","because دلیل را معرفی می‌کند."],["If you practise, you will improve.","اگر تمرین کنی پیشرفت خواهی کرد.","در شرط واقعی آینده، بخش if معمولاً حال ساده دارد."]],"dialogue":[["A","Why are you learning English?","چرا انگلیسی یاد می‌گیری؟"],["B","Because I want to travel.","چون می‌خواهم سفر کنم."],["A","What will you do when you finish this level?","وقتی این سطح را تمام کنی چه می‌کنی؟"],["B","I'll start the next level, so I can improve more.","سطح بعدی را شروع می‌کنم تا بیشتر پیشرفت کنم."]],"reading":"If the weather is good tomorrow, we'll visit the lake. We'll leave early because the journey takes two hours, so we need to prepare tonight.","readingFa":"اگر فردا هوا خوب باشد، از دریاچه دیدن می‌کنیم. زود حرکت می‌کنیم چون سفر دو ساعت طول می‌کشد، بنابراین باید امشب آماده شویم.","mistakes":"در شرط آینده پس از if معمولاً will نمی‌آوریم: If it will rain نادرست است؛ If it rains درست است.","writing":"یک برنامه برای روز تعطیل بنویس و در آن because، so، when و if را به کار ببر.","questions":[["I stayed home ___ I was ill.",["because","so","if"],0],["It was late, ___ we took a taxi.",["because","so","when"],1],["___ I arrive, I'll text you.",["If","When","Because"],1],["If it ___, we'll stay home.",["will rain","rains","rained"],1],["Which word introduces a reason?",["because","so","if"],0]]},{"id":19,"unit":"واحد ۸ · جمله‌های پیوسته","title":"ضمیرهای مفعولی و ملکی","description":"از me، him، us و ضمیرهای ملکی درست استفاده کن.","goal":"تمایز subject/object pronouns و possessive pronouns.","explanation":"ضمیر فاعلی انجام‌دهنده کار است: I, he, we. ضمیر مفعولی بعد از فعل یا حرف اضافه می‌آید: me, him, us. صفات ملکی قبل از اسم‌اند (my book)؛ ضمیر ملکی بدون اسم می‌آید (mine).","steps":[["فاعل و مفعول","She called me. She فاعل و me مفعول است."],["جدول مفعولی","I/me، you/you، he/him، she/her، we/us، they/them."],["صفت ملکی","my, your, his, her, our, their + noun."],["ضمیر ملکی","mine, yours, his, hers, ours, theirs بدون اسم می‌آیند."]],"vocabulary":[["me","من را / به من"],["him","او را (مذکر)"],["us","ما را / به ما"],["theirs","مال آن‌ها"],["ours","مال ما"],["hers","مال او (مونث)"]],"examples":[["Can you help me?","می‌توانی به من کمک کنی؟","بعد از help از ضمیر مفعولی me استفاده می‌شود."],["This seat is ours.","این صندلی مال ماست.","ours بدون اسم می‌آید."]],"dialogue":[["A","Is this your notebook?","این دفتر توست؟"],["B","No, mine is blue. This one is hers.","نه، مال من آبی است. این یکی مال اوست."],["A","Can you give it to her?","می‌توانی آن را به او بدهی؟"],["B","Of course.","البته."]],"reading":"Our neighbours invited us to their house. We brought them a small gift. Their garden is beautiful, and ours is much smaller.","readingFa":"همسایه‌هایمان ما را به خانه‌شان دعوت کردند. برایشان هدیه کوچکی بردیم. باغ آن‌ها زیباست و باغ ما خیلی کوچک‌تر است.","mistakes":"بعد از حرف اضافه از ضمیر مفعولی استفاده کن: for him، with us. This is mine درست است؛ This is my بدون اسم کامل نیست.","writing":"درباره وسایل خودت و دوستانت با me، them، ours و theirs پنج جمله بنویس.","questions":[["Please call ___.",["I","me","my"],1],["This is ___ book.",["mine","my","me"],1],["The red bag is ___.",["her","hers","she"],1],["He gave ___ a present.",["we","our","us"],2],["Which is correct?",["This phone is mine.","This phone is my.","This phone is me."],0]]},{"id":20,"unit":"واحد ۹ · توصیف دقیق‌تر","title":"too و enough","description":"درباره بیش‌ازحد بودن یا کافی بودن مقدار و ویژگی صحبت کن.","goal":"جایگاه too و enough را با صفت و اسم درست به کار ببری.","explanation":"too پیش از صفت یا قید می‌آید و بیش‌ازحد بودن را نشان می‌دهد: too expensive. enough بعد از صفت می‌آید: old enough، اما پیش از اسم: enough money.","steps":[["too + adjective","The coffee is too hot."],["adjective + enough","He isn't tall enough."],["enough + noun","We have enough time."],["too much/many","too much sugar و too many people."]],"vocabulary":[["too","بیش از حد"],["enough","به اندازه کافی"],["comfortable","راحت"],["expensive","گران"],["space","فضا"],["crowded","شلوغ"]],"examples":[["This box is too heavy to carry.","این جعبه برای حمل کردن بیش از حد سنگین است.","too پیش از صفت آمده است."],["We have enough chairs for everyone.","برای همه صندلی کافی داریم.","enough پیش از اسم chairs آمده است."]],"dialogue":[["A","Can we walk to the station?","می‌توانیم تا ایستگاه پیاده برویم؟"],["B","It's too far.","خیلی دور است."],["A","Do we have enough time for a taxi?","برای تاکسی وقت کافی داریم؟"],["B","Yes, we have enough time.","بله، وقت کافی داریم."]],"reading":"The room was too small for twenty people. There weren't enough chairs, and it was too hot. We didn't have enough space to move comfortably.","readingFa":"اتاق برای بیست نفر بیش از حد کوچک بود. صندلی کافی نبود و هوا خیلی گرم بود. فضای کافی برای حرکت راحت نداشتیم.","mistakes":"too enough ترتیب درستی نیست. بگو warm enough؛ اما too warm. enough قبل از اسم می‌آید.","writing":"اتاق یا کلاس خود را با too و enough در پنج جمله توصیف کن.","questions":[["The bag is ___ heavy.",["enough","too","many"],1],["He is old ___ to drive.",["enough","too","much"],0],["We don't have ___ chairs.",["enough","too","many enough"],0],["There are ___ people here.",["too much","too many","enough many"],1],["Which is correct?",["enough warm","warm enough","too enough warm"],1]]},{"id":21,"unit":"واحد ۱۰ · سفر و شهر","title":"حروف اضافه حرکت و مسیر","description":"مسیر و حرکت در شهر را دقیق‌تر توضیح بده.","goal":"استفاده از across، through، along، past و towards.","explanation":"حروف اضافه حرکت مسیر را نشان می‌دهند: across از یک سمت به سمت دیگر، through از داخل، along در امتداد، past از کنار و towards به سمت یک مقصد.","steps":[["across","Walk across the street؛ از عرض خیابان عبور کن."],["through","Go through the park؛ از داخل پارک برو."],["along","Walk along the river؛ در امتداد رودخانه راه برو."],["past / towards","Go past the bank و walk towards the station."]],"vocabulary":[["across","از عرض / آن‌سوی"],["through","از داخل"],["along","در امتداد"],["past","از کنار"],["towards","به سمت"],["corner","گوشه خیابان"]],"examples":[["Walk through the park and turn left.","از داخل پارک عبور کن و به چپ بپیچ.","through حرکت از داخل یک فضا را نشان می‌دهد."],["Go past the bank.","از کنار بانک عبور کن.","past یعنی عبور از کنار یک مکان."]],"dialogue":[["A","How can I get to the museum?","چطور به موزه بروم؟"],["B","Walk along this road and go past the bank.","در امتداد این جاده برو و از کنار بانک عبور کن."],["A","Do I go through the park?","از داخل پارک بروم؟"],["B","Yes, then cross the bridge.","بله، سپس از پل عبور کن."]],"reading":"To reach the museum, walk along Green Street. Go past the supermarket and through the small park. Then walk across the bridge. The museum is on your right.","readingFa":"برای رسیدن به موزه، در امتداد خیابان گرین برو. از کنار سوپرمارکت و از داخل پارک کوچک عبور کن. سپس از پل بگذر. موزه سمت راست توست.","mistakes":"across معمولاً عبور از سطح یا عرض را نشان می‌دهد؛ through برای حرکت از داخل فضای محصور است.","writing":"از خانه تا یک مکان نزدیک را در ۵ مرحله با حروف اضافه حرکت توضیح بده.","questions":[["Walk ___ the bridge to reach the other side.",["across","through","towards"],0],["We walked ___ the tunnel.",["along","through","past"],1],["Go ___ the school; the shop is next to it.",["past","inside","across"],0],["Walk ___ the river.",["through","along","across"],1],["Which means «به سمت»?",["towards","past","across"],0]]},{"id":22,"unit":"واحد ۱۰ · سفر و شهر","title":"در هتل و فرودگاه","description":"در سفر درخواست بده، اطلاعات بپرس و مشکل ساده را توضیح بده.","goal":"استفاده از عبارت‌های کاربردی برای رزرو، پذیرش و سفر.","explanation":"در موقعیت سفر از عبارت‌های مؤدبانه و روشن استفاده کن: I'd like to check in، Could I have…? و What time does…? اطلاعاتی مانند booking، passport، platform و luggage مهم‌اند.","steps":[["پذیرش هتل","I have a reservation under the name…"],["درخواست مؤدبانه","Could I have another key, please?"],["اطلاعات پرواز","Which gate does the flight leave from?"],["بیان مشکل","My room is too noisy. Could you help me?"]],"vocabulary":[["reservation","رزرو"],["reception","پذیرش"],["luggage","چمدان و بار"],["boarding pass","کارت پرواز"],["platform","سکوی ایستگاه"],["departure","حرکت / خروج"]],"examples":[["I'd like to check in, please.","می‌خواهم پذیرش شوم، لطفاً.","عبارت مؤدبانه برای ورود به هتل."],["Could you tell me which platform I need?","می‌توانید بگویید به کدام سکو نیاز دارم؟","Could you برای درخواست مؤدبانه است."]],"dialogue":[["A","Good evening. I have a reservation.","عصر بخیر. رزرو دارم."],["B","Certainly. May I see your passport?","حتماً. می‌توانم گذرنامه‌تان را ببینم؟"],["A","Here you are. Is breakfast included?","بفرمایید. صبحانه شامل می‌شود؟"],["B","Yes, it's served from seven to ten.","بله، از هفت تا ده سرو می‌شود."]],"reading":"At the airport, check the departure screen first. Keep your passport and boarding pass ready. If you cannot find your gate, ask a member of staff for help.","readingFa":"در فرودگاه ابتدا صفحه پروازهای خروجی را بررسی کن. گذرنامه و کارت پروازت را آماده نگه دار. اگر دروازه پرواز را پیدا نکردی، از یکی از کارکنان کمک بخواه.","mistakes":"luggage معمولاً غیرقابل‌شمارش است؛ many luggages نادرست است. بگو a lot of luggage یا two bags.","writing":"یک گفت‌وگوی ۸ خطی در پذیرش هتل بنویس که در آن درخواست اتاق و پرسش درباره صبحانه وجود داشته باشد.","questions":[["A place where you check in at a hotel is…",["reception","platform","runway"],0],["You show this before boarding a plane.",["menu","boarding pass","receipt"],1],["I'd like to ___ in, please.",["check","checking","checked"],0],["Which is a polite request?",["Give me a key.","Could I have a key, please?","I want key now."],1],["Luggage is usually…",["countable","uncountable","a verb"],1]]},{"id":23,"unit":"واحد ۱۱ · ارتباط و خدمات","title":"خرید، بازگشت کالا و خدمات","description":"در فروشگاه درباره اندازه، تعویض و بازپرداخت صحبت کن.","goal":"استفاده از عبارت‌های مؤدبانه برای خرید و توضیح مشکل کالا.","explanation":"برای خرید از Could I try it on?، Do you have this in a larger size? و Can I return it? استفاده کن. رسید خرید receipt است و refund بازپرداخت وجه.","steps":[["پرسیدن اندازه","Do you have this in medium?"],["اتاق پرو","Could I try it on?"],["توضیح مشکل","It doesn't fit. / It's damaged."],["بازگشت کالا","I'd like to return this and get a refund."]],"vocabulary":[["receipt","رسید"],["refund","بازپرداخت"],["exchange","تعویض"],["fit","اندازه بودن"],["damaged","آسیب‌دیده"],["discount","تخفیف"]],"examples":[["These shoes don't fit me.","این کفش‌ها اندازه من نیستند.","fit درباره مناسب بودن اندازه است."],["Could I exchange this for a larger size?","می‌توانم این را با اندازه بزرگ‌تر عوض کنم؟","Could I برای درخواست مؤدبانه است."]],"dialogue":[["A","Can I help you?","می‌توانم کمکتان کنم؟"],["B","Yes, I'd like to return this shirt.","بله، می‌خواهم این پیراهن را پس بدهم."],["A","Is there a problem with it?","مشکلی دارد؟"],["B","Yes, it's damaged. Here's the receipt.","بله، آسیب دیده است. این هم رسید."]],"reading":"A customer bought a jacket yesterday, but the zip doesn't work. She returned to the shop with the receipt and asked for an exchange. The shop assistant offered a new jacket.","readingFa":"مشتری دیروز ژاکتی خرید، اما زیپ آن کار نمی‌کند. او با رسید به فروشگاه برگشت و درخواست تعویض کرد. فروشنده ژاکت جدیدی پیشنهاد داد.","mistakes":"return یعنی پس دادن کالا؛ exchange یعنی تعویض؛ refund یعنی پس گرفتن پول. این سه واژه معنای یکسان ندارند.","writing":"یک مکالمه بین مشتری و فروشنده بنویس که کالا مشکل دارد و مشتری درخواست تعویض می‌کند.","questions":[["A paper that proves you paid is a…",["receipt","refund","discount"],0],["The jacket doesn't ___ me.",["fit","fits to","fitting"],0],["Money returned to a customer is a…",["exchange","refund","receipt"],1],["Which is a polite request?",["Could I try it on?","I try this now.","Give me this."],0],["The product is broken. It is…",["damaged","discounted","available"],0]]},{"id":24,"unit":"واحد ۱۱ · ارتباط و خدمات","title":"تلفن و پیام‌رسانی","description":"تماس تلفنی برقرار کن، پیام بگذار و درخواست تکرار داشته باش.","goal":"عبارت‌های رایج تماس و پیام را درک و استفاده کنی.","explanation":"در تماس تلفنی ممکن است صدا واضح نباشد؛ از Could you repeat that? یا Could you speak more slowly? استفاده کن. برای وصل کردن تماس می‌گوییم put you through و برای پیام leave a message.","steps":[["شروع تماس","Hello, this is Sara speaking."],["درخواست شخص","Could I speak to Mr Brown, please?"],["درخواست تکرار","Sorry, I didn't catch that. Could you repeat it?"],["پیام گذاشتن","Can I leave a message?"]],"vocabulary":[["call back","دوباره تماس گرفتن"],["line","خط تلفن"],["message","پیام"],["available","در دسترس"],["hold on","منتظر ماندن"],["speak up","بلندتر صحبت کردن"]],"examples":[["Could you speak a little more slowly?","می‌توانید کمی آهسته‌تر صحبت کنید؟","درخواست مؤدبانه برای فهم بهتر."],["I'll call you back in ten minutes.","ده دقیقه دیگر دوباره تماس می‌گیرم.","call back یعنی دوباره تماس گرفتن."]],"dialogue":[["A","Hello, could I speak to Anna?","سلام، می‌توانم با آنا صحبت کنم؟"],["B","I'm afraid she's not available.","متأسفم، او در دسترس نیست."],["A","Could I leave a message?","می‌توانم پیامی بگذارم؟"],["B","Of course. I'll give it to her.","البته. پیام را به او می‌دهم."]],"reading":"Tom called the travel office, but the line was busy. He called back ten minutes later and asked the assistant to repeat the departure time. He wrote the information in his notebook.","readingFa":"تام با دفتر مسافرت تماس گرفت، اما خط مشغول بود. ده دقیقه بعد دوباره تماس گرفت و از مسئول خواست ساعت حرکت را تکرار کند. اطلاعات را در دفترش نوشت.","mistakes":"در تلفن برای معرفی خود می‌توانی بگویی This is Tom. عبارت I'm Tom هم در مکالمه ممکن است، اما الگوی تلفنی رایج This is است.","writing":"یک تماس تلفنی کوتاه برای تغییر زمان قرار بنویس.","questions":[["Could I ___ to the manager?",["speak","speaking","spoke"],0],["The line is busy. I'll call you ___.",["back","out","off"],0],["Could you ___ that, please?",["repeat","repeated","repeating"],0],["A message is something you…",["leave","drive","wear"],0],["Which is a polite phone phrase?",["Speak now!","Could you hold on, please?","Who are you?"],1]]}];
export const a2AnswerKeys: Record<number, number[]> = {"1":[0,1,1,2,2],"2":[1,0,1,0,1],"3":[1,2,0,0,2],"4":[0,2,1,0,2],"5":[1,1,0,2,1],"6":[1,0,0,1,0],"7":[0,1,1,2,0],"8":[0,1,1,2,0],"9":[1,0,0,0,0],"10":[0,1,1,0,2],"11":[1,0,1,1,0],"12":[0,1,1,1,0],"13":[1,2,1,1,2],"14":[0,1,1,0,1],"15":[0,1,2,2,1],"16":[1,1,1,1,1],"17":[2,0,1,0,0],"18":[0,1,1,1,0],"19":[1,1,1,2,0],"20":[1,0,0,1,1],"21":[0,1,0,1,0],"22":[0,1,0,1,1],"23":[0,0,1,0,0],"24":[0,0,0,0,1]};
export const a2Units = [...new Set(a2Lessons.map(lesson=>lesson.unit))].map(unit=>({unit,lessons:a2Lessons.filter(lesson=>lesson.unit===unit)}));
